const fs = require\('fs'\);
let c = fs.readFileSync\('src/screens/RankingScreen.tsx', 'utf8'\);
c = c.replace\('.from\(\\"vw_ranking_mensal\\"\)', '.from\(\\"v_ranking_mensal_rcc\\"\)'\);
c = c.replace\('.from\(\\"vw_posicao_recruta_mes\\"\)', '.from\(\\"v_posicao_recruta_mes_rcc\\"\)'\);
c = c.split\('\\n'\).filter\(l => !l.includes\('.eq\(\\"recruta_id\\", recrutaId\)'\)\).join\('\\n'\);
c = c.replace\('.from\(\\"campeoes_mensais\\"\)', '.from\(\\"v_campeoes_mensais_rcc\\"\)'\);
fs.writeFileSync\('src/screens/RankingScreen.tsx', c\);
console.log\('rcc changes applied'\);
")

